To enhance the table filtering in the `Leads` component, I will add a search input field and implement a multi-column, case-insensitive filter.

Here is the plan:
1.  **Update `components/Leads.tsx`**:
    *   Add `IconSearch` to imports.
    *   Add `searchQuery` state.
    *   Implement `filteredLeads` logic using `useMemo` to filter by name, company, email, or status.
    *   Add a search input field in the header area.
    *   Update the table to render `filteredLeads` and show a "No results" message if empty.

# Updated files:

## components/Leads.tsx

```tsx
import React, { useState, useMemo } from 'react';
import { Lead, EmailTemplate } from '../types';
import { analyzeLeadWithAI, generateEmailDraft } from '../services/geminiService';
import { IconSparkles, IconX, IconSend, IconSave, IconFileText, IconInfo, IconSearch } from './Icons';
import { MOCK_TEMPLATES } from '../constants';

interface LeadsProps {
  leads: Lead[];
}

const Leads: React.FC<LeadsProps> = ({ leads }) => {
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [emailDraft, setEmailDraft] = useState<string>('');
  const [isDrafting, setIsDrafting] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Template State
  const [templates, setTemplates] = useState<EmailTemplate[]>(MOCK_TEMPLATES);
  const [isSavingTemplate, setIsSavingTemplate] = useState(false);
  const [newTemplateName, setNewTemplateName] = useState('');

  // Search/Filter Logic
  const filteredLeads = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return leads;

    return leads.filter((lead) => 
      lead.name.toLowerCase().includes(query) ||
      lead.company.toLowerCase().includes(query) ||
      lead.email.toLowerCase().includes(query) ||
      lead.status.toLowerCase().includes(query)
    );
  }, [leads, searchQuery]);

  const handleAnalyze = async (lead: Lead) => {
    setSelectedLead(lead);
    setIsAnalyzing(true);
    setAnalysis('');
    setEmailDraft('');
    const result = await analyzeLeadWithAI(lead);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleDraftEmail = async (tone: 'formal' | 'casual' | 'persuasive') => {
    if (!selectedLead) return;
    setIsDrafting(true);
    const draft = await generateEmailDraft(selectedLead, tone);
    setEmailDraft(draft);
    setIsDrafting(false);
  };

  const handleLoadTemplate = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const templateId = e.target.value;
    const template = templates.find(t => t.id === templateId);
    if (template && selectedLead) {
      let body = template.body;
      // Simple variable substitution
      body = body.replace(/{{name}}/g, selectedLead.name);
      body = body.replace(/{{company}}/g, selectedLead.company);
      setEmailDraft(body);
    }
  };

  const handleSaveTemplate = () => {
    if (!newTemplateName.trim() || !emailDraft) return;
    const newTemplate: EmailTemplate = {
      id: Date.now().toString(),
      name: newTemplateName.trim(),
      subject: 'Saved Template', 
      body: emailDraft
    };
    setTemplates([...templates, newTemplate]);
    setIsSavingTemplate(false);
    setNewTemplateName('');
  };

  const closeModal = () => {
    setSelectedLead(null);
    setAnalysis('');
    setEmailDraft('');
    setIsSavingTemplate(false);
    setNewTemplateName('');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Smart Leads</h1>

        {/* Search Input */}
        <div className="relative w-full sm:w-auto">
          <IconSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input
            type="text"
            placeholder="Search name, company, status..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full sm:w-64 pl-10 pr-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg text-sm text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-purple-500 placeholder-slate-400 transition-colors"
          />
        </div>
      </div>

      {/* Leads Table */}
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none transition-colors duration-300 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="text-xs font-semibold tracking-wide text-slate-500 uppercase bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                <th className="px-6 py-4 whitespace-nowrap">Name</th>
                <th className="px-6 py-4 whitespace-nowrap">Company</th>
                <th className="px-6 py-4 whitespace-nowrap">Status</th>
                <th className="px-6 py-4 whitespace-nowrap">Value</th>
                <th className="px-6 py-4 whitespace-nowrap">AI Score</th>
                <th className="px-6 py-4 whitespace-nowrap">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {filteredLeads.length > 0 ? (
                filteredLeads.map((lead) => (
                  <tr key={lead.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                    <td className="px-6 py-4 font-medium text-slate-900 dark:text-white whitespace-nowrap">{lead.name}</td>
                    <td className="px-6 py-4 text-slate-500 dark:text-slate-400 whitespace-nowrap">{lead.company}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${
                        lead.score > 80 ? 'bg-emerald-100 text-emerald-700 border border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20' : 
                        lead.score > 50 ? 'bg-yellow-100 text-yellow-700 border border-yellow-200 dark:bg-yellow-500/10 dark:text-yellow-400 dark:border-yellow-500/20' :
                        'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300'
                      }`}>
                        {lead.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300 whitespace-nowrap">${lead.value.toLocaleString()}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center gap-3">
                        <div className="flex-1 flex items-center min-w-[100px]">
                          <div className="w-16 h-2 bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden mr-2">
                            <div 
                              className={`h-full rounded-full ${
                                lead.score > 75 ? 'bg-gradient-to-r from-emerald-500 to-emerald-400' :
                                lead.score > 40 ? 'bg-gradient-to-r from-yellow-500 to-yellow-400' :
                                'bg-slate-400 dark:bg-slate-600'
                              }`} 
                              style={{ width: `${lead.score}%` }}
                            />
                          </div>
                          <span className="text-sm font-bold text-slate-700 dark:text-white">{lead.score}</span>
                        </div>

                        {/* Tooltip Wrapper */}
                        <div className="relative group/tooltip">
                          <IconInfo className="w-4 h-4 text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 cursor-help transition-colors" />

                          {/* Tooltip Dropdown */}
                          <div className="absolute right-0 bottom-full mb-2 w-48 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-xl rounded-lg p-3 z-50 opacity-0 invisible group-hover/tooltip:opacity-100 group-hover/tooltip:visible transition-all duration-200 transform translate-y-2 group-hover/tooltip:translate-y-0">
                            <div className="text-xs font-bold text-slate-900 dark:text-white mb-2 pb-2 border-b border-slate-100 dark:border-slate-700">
                              Score Breakdown
                            </div>
                            <div className="space-y-2 text-xs">
                              <div className="flex justify-between items-center">
                                <span className="text-slate-500 dark:text-slate-400">Profile Fit</span>
                                <span className="font-semibold text-emerald-600 dark:text-emerald-400">{lead.scoreBreakdown.fit}%</span>
                              </div>
                              <div className="flex justify-between items-center">
                                <span className="text-slate-500 dark:text-slate-400">Engagement</span>
                                <span className="font-semibold text-purple-600 dark:text-purple-400">{lead.scoreBreakdown.engagement}%</span>
                              </div>
                              <div className="flex justify-between items-center">
                                <span className="text-slate-500 dark:text-slate-400">Budget</span>
                                <span className="font-semibold text-blue-600 dark:text-blue-400">{lead.scoreBreakdown.budget}%</span>
                              </div>
                            </div>
                            {/* Arrow */}
                            <div className="absolute bottom-0 right-1 translate-y-1/2 rotate-45 w-2 h-2 bg-white dark:bg-slate-800 border-b border-r border-slate-200 dark:border-slate-700"></div>
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <button 
                        onClick={() => handleAnalyze(lead)}
                        className="flex items-center px-3 py-1.5 text-xs font-medium text-purple-600 dark:text-purple-400 bg-purple-100 dark:bg-purple-500/10 rounded-md hover:bg-purple-200 dark:hover:bg-purple-500/20 transition-all border border-purple-200 dark:border-purple-500/20"
                      >
                        <IconSparkles className="w-3 h-3 mr-1" />
                        Analyze
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                    <div className="flex flex-col items-center justify-center">
                      <IconSearch className="w-8 h-8 mb-2 opacity-20" />
                      <p>No leads found matching "{searchQuery}"</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* AI Analysis Modal */}
      {selectedLead && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                <IconSparkles className="w-5 h-5 text-purple-600 dark:text-purple-500 mr-2" />
                AI Analysis: {selectedLead.name}
              </h2>
              <button onClick={closeModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors">
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 overflow-y-auto space-y-6">
              <div className="bg-slate-50 dark:bg-slate-950 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-2 uppercase tracking-wider">Strategic Insight</h3>
                {isAnalyzing ? (
                   <div className="flex items-center space-x-2 text-purple-500 animate-pulse">
                     <IconSparkles className="w-4 h-4" />
                     <span>Analyzing lead data with Gemini...</span>
                   </div>
                ) : (
                  <div className="text-slate-700 dark:text-slate-200 prose prose-slate dark:prose-invert max-w-none text-sm leading-relaxed whitespace-pre-wrap">
                    {analysis}
                  </div>
                )}
              </div>

              <div>
                <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-3 uppercase tracking-wider">Email Composer</h3>

                {/* Email Controls */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
                  <div className="flex space-x-2">
                    <button onClick={() => handleDraftEmail('formal')} className="px-3 py-1.5 text-xs font-medium text-slate-700 dark:text-white bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg border border-slate-200 dark:border-slate-700 transition-colors flex items-center">
                      <IconSparkles className="w-3 h-3 mr-1" /> AI: Formal
                    </button>
                    <button onClick={() => handleDraftEmail('persuasive')} className="px-3 py-1.5 text-xs font-medium text-white bg-purple-600 hover:bg-purple-500 rounded-lg shadow transition-colors flex items-center">
                      <IconSparkles className="w-3 h-3 mr-1" /> AI: Persuasive
                    </button>
                  </div>

                  <div className="flex items-center">
                    <IconFileText className="w-4 h-4 text-slate-400 mr-2" />
                    <select 
                      onChange={handleLoadTemplate}
                      className="text-xs p-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-purple-500 cursor-pointer"
                    >
                      <option value="">Load Template...</option>
                      {templates.map(t => (
                        <option key={t.id} value={t.id}>{t.name}</option>
                      ))}
                    </select>
                  </div>
                </div>

                {isDrafting && <div className="text-sm text-slate-500 dark:text-slate-400 animate-pulse mb-2">Drafting email...</div>}

                {/* Email Editor */}
                <div className="relative">
                  <textarea
                    value={emailDraft}
                    onChange={(e) => setEmailDraft(e.target.value)}
                    placeholder="Draft your email here..."
                    className="w-full h-48 p-4 text-sm bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-700 dark:text-slate-200 font-mono resize-none transition-all"
                  />

                  {/* Bottom Actions */}
                  <div className="flex justify-between items-center mt-3">
                    <div className="flex items-center">
                      {!isSavingTemplate ? (
                        <button 
                          onClick={() => setIsSavingTemplate(true)}
                          disabled={!emailDraft}
                          className="text-xs flex items-center text-slate-500 hover:text-purple-600 dark:text-slate-400 dark:hover:text-purple-400 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          <IconSave className="w-3 h-3 mr-1" /> Save as Template
                        </button>
                      ) : (
                        <div className="flex items-center space-x-2 animate-fade-in">
                          <input 
                            type="text" 
                            value={newTemplateName}
                            onChange={(e) => setNewTemplateName(e.target.value)}
                            placeholder="Template Name"
                            className="text-xs px-2 py-1 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded focus:outline-none focus:border-purple-500 text-slate-900 dark:text-white"
                            autoFocus
                          />
                          <button 
                            onClick={handleSaveTemplate}
                            className="text-xs px-2 py-1 bg-purple-600 text-white rounded hover:bg-purple-500 transition-colors"
                          >
                            Save
                          </button>
                          <button 
                            onClick={() => { setIsSavingTemplate(false); setNewTemplateName(''); }}
                            className="text-xs px-2 py-1 text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                          >
                            Cancel
                          </button>
                        </div>
                      )}
                    </div>

                    <button 
                      onClick={() => navigator.clipboard.writeText(emailDraft)}
                      disabled={!emailDraft}
                      className="px-4 py-2 text-xs font-medium text-purple-600 dark:text-purple-400 hover:text-purple-700 dark:hover:text-purple-300 bg-purple-50 dark:bg-purple-500/10 hover:bg-purple-100 dark:hover:bg-purple-500/20 rounded-lg transition-colors flex items-center disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <IconSend className="w-3 h-3 mr-1.5" /> Copy to Clipboard
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Leads;

To implement the requested change, I will update the `Pipeline` component to enhance the Activity Log section within the deal modal. I'll add visual badges for the activity `type` and ensure the layout clearly displays the type, description, and timestamp for each entry.

