## components/Pipeline.tsx

```tsx
import React, { useState, useMemo, useEffect } from 'react';
import { Deal, Activity } from '../types';
import { IconX, IconMail, IconPhone, IconFilter, IconHistory, IconClock } from './Icons';

interface PipelineProps {
  deals: Deal[];
  onAddDeal: (deal: Deal) => void;
  onUpdateDeal: (deal: Deal) => void;
}

const Pipeline: React.FC<PipelineProps> = ({ deals, onAddDeal, onUpdateDeal }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [draggedDealId, setDraggedDealId] = useState<string | null>(null);
  const [selectedDeal, setSelectedDeal] = useState<Deal | null>(null);

  const initialFormState = {
    title: '',
    company: '',
    value: '',
    closeDate: '',
    stage: 'Qualification' as Deal['stage'],
    email: '',
    phone: '',
    probability: 50
  };

  const [formData, setFormData] = useState(initialFormState);

  // Reset form or populate when modal opens/closes or selection changes
  useEffect(() => {
    if (selectedDeal) {
      setFormData({
        title: selectedDeal.title,
        company: selectedDeal.company,
        value: selectedDeal.value.toString(),
        closeDate: selectedDeal.closeDate,
        stage: selectedDeal.stage,
        email: selectedDeal.email || '',
        phone: selectedDeal.phone || '',
        probability: selectedDeal.probability
      });
    } else {
      setFormData(initialFormState);
    }
  }, [selectedDeal]);

  const handleOpenNewDeal = () => {
    setSelectedDeal(null);
    setIsModalOpen(true);
  };

  const handleOpenEditDeal = (deal: Deal) => {
    setSelectedDeal(deal);
    setIsModalOpen(true);
  };

  // Filter States
  const [filterCompany, setFilterCompany] = useState('');
  const [filterDate, setFilterDate] = useState('');

  // Derived Options for Dropdowns
  const uniqueCompanies = useMemo(() => Array.from(new Set(deals.map(d => d.company))).sort(), [deals]);
  const uniqueDates = useMemo(() => Array.from(new Set(deals.map(d => d.closeDate))).sort(), [deals]);

  // Filter Logic
  const filteredDeals = useMemo(() => {
    return deals.filter(deal => {
      const matchesCompany = filterCompany ? deal.company === filterCompany : true;
      const matchesDate = filterDate ? deal.closeDate === filterDate : true;
      return matchesCompany && matchesDate;
    });
  }, [deals, filterCompany, filterDate]);

  const columns = [
    { id: 'Qualification', label: 'Qualification', color: 'bg-slate-500' },
    { id: 'Needs Analysis', label: 'Needs Analysis', color: 'bg-blue-500' },
    { id: 'Value Proposition', label: 'Value Proposition', color: 'bg-indigo-500' },
    { id: 'Id. Decision Makers', label: 'Id. Decision Makers', color: 'bg-purple-500' },
    { id: 'Proposal/Price Quote', label: 'Proposal/Price Quote', color: 'bg-yellow-500' },
    { id: 'Negotiation/Review', label: 'Negotiation/Review', color: 'bg-orange-500' },
    { id: 'Closed Won', label: 'Closed Won', color: 'bg-emerald-500' },
    { id: 'Closed Lost', label: 'Closed Lost', color: 'bg-red-500' },
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedDeal) {
      // Edit Mode
      const updatedDeal: Deal = {
        ...selectedDeal,
        title: formData.title,
        company: formData.company,
        value: Number(formData.value),
        stage: formData.stage,
        closeDate: formData.closeDate,
        probability: Number(formData.probability),
        email: formData.email,
        phone: formData.phone
      };
      onUpdateDeal(updatedDeal);
    } else {
      // Create Mode
      const newDeal: Deal = {
        id: Date.now().toString(),
        title: formData.title,
        company: formData.company,
        value: Number(formData.value),
        stage: formData.stage,
        closeDate: formData.closeDate || new Date().toISOString().split('T')[0],
        probability: Number(formData.probability),
        email: formData.email,
        phone: formData.phone,
        activities: []
      };
      onAddDeal(newDeal);
    }

    setIsModalOpen(false);
    setSelectedDeal(null);
  };

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, dealId: string) => {
    setDraggedDealId(dealId);
    e.dataTransfer.setData('dealId', dealId);
    e.dataTransfer.effectAllowed = 'move';
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  const handleDragEnd = (e: React.DragEvent) => {
    setDraggedDealId(null);
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, stageId: string) => {
    e.preventDefault();
    const dealId = e.dataTransfer.getData('dealId');
    const deal = deals.find(d => d.id === dealId);

    if (deal && deal.stage !== stageId) {
      onUpdateDeal({ ...deal, stage: stageId as Deal['stage'] });
    }
  };

  // Helper functions for Activity Log styling
  const getActivityTypeStyle = (type: Activity['type']) => {
    switch (type) {
      case 'created':
        return 'bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20';
      case 'stage_change':
        return 'bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-500/10 dark:text-blue-400 dark:border-blue-500/20';
      case 'value_change':
        return 'bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-500/10 dark:text-amber-400 dark:border-amber-500/20';
      case 'probability_change':
        return 'bg-purple-100 text-purple-700 border-purple-200 dark:bg-purple-500/10 dark:text-purple-400 dark:border-purple-500/20';
      default:
        return 'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
    }
  };

  const formatActivityType = (type: string) => {
    return type.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Deal Pipeline</h1>
        <button 
          onClick={handleOpenNewDeal}
          className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all"
        >
          + New Deal
        </button>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-wrap items-center gap-4 mb-6 p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none transition-colors">
        <div className="flex items-center text-sm font-medium text-slate-500 dark:text-slate-400">
          <IconFilter className="w-4 h-4 mr-2" />
          Filter by:
        </div>

        <select
          value={filterCompany}
          onChange={(e) => setFilterCompany(e.target.value)}
          className="px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-purple-500 transition-colors cursor-pointer"
        >
          <option value="">All Companies</option>
          {uniqueCompanies.map(c => <option key={c} value={c}>{c}</option>)}
        </select>

        <select
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          className="px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-purple-500 transition-colors cursor-pointer"
        >
          <option value="">All Dates</option>
          {uniqueDates.map(d => <option key={d} value={d}>{d}</option>)}
        </select>

        {(filterCompany || filterDate) && (
          <button
            onClick={() => { setFilterCompany(''); setFilterDate(''); }}
            className="px-3 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-colors"
          >
            Clear Filters
          </button>
        )}
      </div>

      <div className="flex-1 grid grid-cols-1 md:grid-cols-[repeat(8,minmax(300px,1fr))] gap-6 overflow-x-auto pb-4">
        {columns.map((col) => (
          <div 
            key={col.id} 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, col.id)}
            className={`flex flex-col h-full min-w-[300px] bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 ${draggedDealId ? 'border-dashed border-slate-300 dark:border-slate-700' : ''}`}
          >
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <h3 className="font-semibold text-slate-900 dark:text-white truncate pr-2">{col.label}</h3>
              <span className="px-2 py-0.5 text-xs font-bold text-slate-700 dark:text-slate-900 bg-slate-200 dark:bg-slate-200 rounded-full flex-shrink-0">
                {filteredDeals.filter(d => d.stage === col.id).length}
              </span>
            </div>
            <div className="p-4 space-y-4 flex-1 overflow-y-auto">
              {filteredDeals.filter(d => d.stage === col.id).map((deal) => (
                <div 
                  key={deal.id} 
                  draggable
                  onDragStart={(e) => handleDragStart(e, deal.id)}
                  onDragEnd={handleDragEnd}
                  onClick={() => handleOpenEditDeal(deal)}
                  className="p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm hover:shadow-md hover:border-purple-300 dark:hover:border-slate-600 transition-all cursor-move group select-none active:cursor-grabbing"
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{deal.company}</span>
                    <div className={`w-2 h-2 rounded-full ${col.color}`}></div>
                  </div>
                  <h4 className="font-medium text-slate-900 dark:text-white mb-3 group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">{deal.title}</h4>

                  {/* Contact Info */}
                  {(deal.email || deal.phone) && (
                    <div className="mb-3 space-y-1">
                      {deal.email && (
                        <div className="flex items-center text-xs text-slate-500 dark:text-slate-400">
                          <IconMail className="w-3 h-3 mr-1.5 opacity-70" />
                          <span className="truncate max-w-[180px]">{deal.email}</span>
                        </div>
                      )}
                      {deal.phone && (
                        <div className="flex items-center text-xs text-slate-500 dark:text-slate-400">
                          <IconPhone className="w-3 h-3 mr-1.5 opacity-70" />
                          <span>{deal.phone}</span>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="flex justify-between items-center pt-3 border-t border-slate-100 dark:border-slate-700/50">
                    <span className="text-sm font-bold text-slate-700 dark:text-slate-200">${deal.value.toLocaleString()}</span>
                    <div className="flex items-center">
                        <div className="w-16 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mr-2 overflow-hidden">
                            <div className="h-full bg-purple-500 rounded-full" style={{ width: `${deal.probability}%` }}></div>
                        </div>
                        <span className="text-xs text-slate-500">{deal.probability}%</span>
                    </div>
                  </div>
                </div>
              ))}
              {filteredDeals.filter(d => d.stage === col.id).length === 0 && (
                 <div className="flex items-center justify-center h-24 border-2 border-dashed border-slate-300 dark:border-slate-800 rounded-lg text-slate-500 dark:text-slate-600 text-sm">
                   Drop here
                 </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* New/Edit Deal Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                {selectedDeal ? 'Edit Deal' : 'Add New Deal'}
              </h2>
              <button 
                onClick={() => { setIsModalOpen(false); setSelectedDeal(null); }} 
                className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
              >
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <div className="overflow-y-auto p-6">
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Deal Title</label>
                    <input
                      type="text"
                      name="title"
                      required
                      value={formData.title}
                      onChange={handleInputChange}
                      placeholder="e.g. Enterprise License"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Company</label>
                    <input
                      type="text"
                      name="company"
                      required
                      value={formData.company}
                      onChange={handleInputChange}
                      placeholder="e.g. Acme Corp"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Email</label>
                    <input
                      type="email"
                      name="email"
                      value={formData.email}
                      onChange={handleInputChange}
                      placeholder="contact@acme.com"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                    <input
                      type="tel"
                      name="phone"
                      value={formData.phone}
                      onChange={handleInputChange}
                      placeholder="+1 555..."
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Value ($)</label>
                    <input
                      type="number"
                      name="value"
                      required
                      min="0"
                      value={formData.value}
                      onChange={handleInputChange}
                      placeholder="50000"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Close Date</label>
                    <input
                      type="date"
                      name="closeDate"
                      required
                      value={formData.closeDate}
                      onChange={handleInputChange}
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                <div>
                   <div className="flex justify-between items-center mb-1">
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">Probability</label>
                      <span className="text-sm font-bold text-purple-600 dark:text-purple-400">{formData.probability}%</span>
                   </div>
                   <input
                     type="range"
                     name="probability"
                     min="0"
                     max="100"
                     step="5"
                     value={formData.probability}
                     onChange={handleInputChange}
                     className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-600 focus:outline-none focus:ring-2 focus:ring-purple-500/50"
                   />
                   <div className="flex justify-between text-xs text-slate-400 mt-1">
                      <span>0%</span>
                      <span>50%</span>
                      <span>100%</span>
                   </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Stage</label>
                  <select
                    name="stage"
                    value={formData.stage}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"
                  >
                    <option value="Qualification">Qualification</option>
                    <option value="Needs Analysis">Needs Analysis</option>
                    <option value="Value Proposition">Value Proposition</option>
                    <option value="Id. Decision Makers">Id. Decision Makers</option>
                    <option value="Proposal/Price Quote">Proposal/Price Quote</option>
                    <option value="Negotiation/Review">Negotiation/Review</option>
                    <option value="Closed Won">Closed Won</option>
                    <option value="Closed Lost">Closed Lost</option>
                  </select>
                </div>

                <div className="pt-4 flex space-x-3">
                  <button
                    type="button"
                    onClick={() => { setIsModalOpen(false); setSelectedDeal(null); }}
                    className="flex-1 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="flex-1 px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-colors"
                  >
                    {selectedDeal ? 'Update Deal' : 'Create Deal'}
                  </button>
                </div>
              </form>

              {/* Activity Log Section */}
              {selectedDeal && (
                <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-800">
                  <div className="flex items-center mb-4">
                    <IconHistory className="w-5 h-5 text-slate-400 mr-2" />
                    <h3 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wider">Activity Log</h3>
                  </div>

                  <div className="space-y-4 max-h-48 overflow-y-auto pr-2">
                    {selectedDeal.activities && selectedDeal.activities.length > 0 ? (
                      [...selectedDeal.activities].reverse().map((activity) => (
                        <div key={activity.id} className="flex gap-3 text-sm group">
                           <div className="flex flex-col items-center">
                              <div className={`w-2 h-2 rounded-full mt-2 ${
                                activity.type === 'created' ? 'bg-emerald-400' :
                                activity.type === 'stage_change' ? 'bg-blue-400' :
                                'bg-slate-300 dark:bg-slate-600'
                              }`}></div>
                              <div className="w-px h-full bg-slate-200 dark:bg-slate-800 my-1 last:hidden group-last:hidden"></div>
                           </div>
                           <div className="pb-4 w-full">
                             <div className="flex justify-between items-start">
                                <span className={`text-[10px] px-2 py-0.5 rounded-full border font-semibold uppercase tracking-wide mb-1 ${getActivityTypeStyle(activity.type)}`}>
                                 {formatActivityType(activity.type)}
                                </span>
                                <div className="flex items-center text-xs text-slate-400 whitespace-nowrap ml-2">
                                  <IconClock className="w-3 h-3 mr-1" />
                                  {new Date(activity.timestamp).toLocaleString()}
                                </div>
                             </div>
                             <p className="text-slate-700 dark:text-slate-300 mt-1">{activity.description}</p>
                           </div>
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-slate-500 italic">No activity recorded yet.</p>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Pipeline;

