export enum LeadStatus {
  NEW = 'New',
  CONTACTED = 'Contacted',
  QUALIFIED = 'Qualified',
  PROPOSAL = 'Proposal Sent',
  NEGOTIATION = 'Negotiation',
  CLOSED = 'Closed Won',
  LOST = 'Closed Lost'
}

export interface Lead {
  id: string;
  name: string;
  company: string;
  email: string;
  phone: string;
  status: LeadStatus;
  value: number;
  lastContact: string;
  score: number; // 0-100 AI Score
  scoreBreakdown: {
    fit: number;
    engagement: number;
    budget: number;
  };
  notes: string;
  // New fields for enhanced view
  source: string;
  city: string;
  industry: string;
  createdTime: string;
  lastActivity: string;
  leadSource: string; // Specific field for the column
}

export interface Activity {
  id: string;
  type: 'stage_change' | 'value_change' | 'probability_change' | 'update' | 'created' | 'email_sent' | 'meeting_scheduled' | 'follow_up';
  description: string;
  timestamp: string;
}

export interface Deal {
  id: string;
  title: string;
  company: string;
  stage: 'Qualification' | 'Needs Analysis' | 'Value Proposition' | 'Id. Decision Makers' | 'Proposal/Price Quote' | 'Negotiation/Review' | 'Closed Won' | 'Closed Lost';
  value: number;
  probability: number;
  closeDate: string;
  email?: string;
  phone?: string;
  activities: Activity[];
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface DashboardMetrics {
  totalRevenue: number;
  activeLeads: number;
  conversionRate: number;
  avgDealSize: number;
}

export interface EmailTemplate {
  id: string;
  name: string;
  subject: string;
  body: string;
}

export interface Task {
  id: string;
  title: string;
  dueDate: string;
  status: 'Not Started' | 'In Progress' | 'Completed' | 'Deferred';
  priority: 'Low' | 'Normal' | 'High';
  relatedTo?: string;
}

export interface Meeting {
  id: string;
  title: string;
  date: string;
  startTime: string;
  endTime: string;
  type: 'Online' | 'Offline';
  relatedTo: string; // Company or Contact name
}

export interface Contact {
  id: string;
  name: string;
  title: string;
  company: string;
  email: string;
  phone: string;
  lastActivity: string;
}

export interface Account {
  id: string;
  name: string;
  industry: string;
  website: string;
  phone: string;
  owner: string;
}
